"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[30164],{80865:e=>{e.exports=JSON.parse('{"functions":[{"name":"SetForcedLocaleId","desc":"Forces the locale id used for translation, overriding the inferred player/Roblox\\nlocale. Pass nil to clear the override and fall back to the inferred locale. Useful\\nfor an in-game language selector.","params":[{"name":"self","desc":"","lua_type":"TranslatorService"},{"name":"localeId","desc":"","lua_type":"string?"}],"returns":[],"function_type":"static","source":{"line":128,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}},{"name":"SetEntryValue","desc":"Queues a localization table entry value write. Writes are batched and flushed\\ntogether at the end of the frame (via `task.defer`) instead of being applied\\nsynchronously, so a burst of translators loading does not each pay the cost of\\nmutating (and re-replicating) the shared localization table in the load path.\\n\\nA key is therefore not readable the instant it is registered. Gate reads on\\n[TranslatorService.ObserveIsTranslationReady], which tracks the key you are about to read\\nrather than whichever batch happened to be pending.","params":[{"name":"self","desc":"","lua_type":"TranslatorService"},{"name":"translationKey","desc":"","lua_type":"string"},{"name":"source","desc":"","lua_type":"string"},{"name":"context","desc":"","lua_type":"string"},{"name":"localeId","desc":"","lua_type":"string"},{"name":"text","desc":"","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":150,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}},{"name":"SetEntryExample","desc":"Queues a localization table entry example write. See [TranslatorService.SetEntryValue].","params":[{"name":"self","desc":"","lua_type":"TranslatorService"},{"name":"translationKey","desc":"","lua_type":"string"},{"name":"source","desc":"","lua_type":"string"},{"name":"context","desc":"","lua_type":"string"},{"name":"example","desc":"","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":183,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}},{"name":"PromiseEntriesWritten","desc":"Returns a promise that resolves once all currently-queued localization writes\\nhave been flushed to the table. Resolves immediately if nothing is pending.\\n\\nThis answers for the batch pending when it is called, which is not necessarily the batch\\ncarrying the data a reader wants: writes queued while this flush resolves land in the\\nnext one. Gate reads on [TranslatorService.ObserveIsTranslationReady] instead -- this is for\\ncallers that want the current batch settled, such as tests.","params":[{"name":"self","desc":"","lua_type":"TranslatorService"}],"returns":[{"desc":"","lua_type":"Promise"}],"function_type":"static","source":{"line":243,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}},{"name":"IsTranslationReady","desc":"Whether a read of this key would see everything queued for it. False while the key has\\nwrites waiting on the end-of-frame flush.\\n\\n:::warning\\nThis is an implementation detail of the translation stack, exposed for diagnostics.\\nReading a translation through [JSONTranslator] already accounts for it.\\n:::\\n\\nA key nothing has ever queued is ready: there is nothing pending to wait for, and a read\\nshould fall through to whatever the translators can offer rather than block forever.","params":[{"name":"self","desc":"","lua_type":"TranslatorService"},{"name":"translationKey","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":266,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}},{"name":"IsTranslationReadyForLocale","desc":"Whether a read of this key **in this locale** would see everything queued for it. Narrower\\nthan [TranslatorService.IsTranslationReady], which is false while any locale is queued.\\n\\n:::warning\\nThis is an implementation detail of the translation stack, exposed for diagnostics.\\n:::\\n\\nThe distinction matters after a single-key flush ([TranslatorService.FlushEntryForKey]),\\nwhich lands the locales a read can consult but leaves the entry queued for the rest. The\\nkey is readable in that locale while still not ready overall, so a failure to translate it\\nis a real failure and worth reporting.","params":[{"name":"self","desc":"","lua_type":"TranslatorService"},{"name":"translationKey","desc":"","lua_type":"string"},{"name":"localeId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":289,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}},{"name":"ObserveIsTranslationReady","desc":"Observes whether a read of this key would see everything queued for it, firing the\\ncurrent state immediately and again on every change.\\n\\n:::warning\\nThis is an implementation detail of the translation stack, exposed for diagnostics. Every\\nway of reading a translation through [JSONTranslator] already waits for the key it reads,\\nso consumers should not have to gate on this themselves.\\n:::\\n\\nThis is the reactive counterpart to the batching: writes are deliberately deferred to the\\nend of the frame (see [TranslatorService.SetEntryValue]), so a reader that translates the\\ninstant a key is registered reads before the write lands. Rather than forcing the flush --\\nwhich would defeat the batching that keeps a streaming-in game from writing the table\\nthousands of times a frame -- [JSONTranslator] observes this and re-reads when it goes\\nready.\\n\\nEmissions are driven by the queue and flush directly, so nothing here yields.","params":[{"name":"self","desc":"","lua_type":"TranslatorService"},{"name":"translationKey","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"Observable<boolean>"}],"function_type":"static","source":{"line":327,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}},{"name":"FlushEntriesForTesting","desc":"Flushes every pending localization write synchronously. This defeats the end-of-frame\\nbatching and pays the full table write cost, so it exists for tests that need the table\\nsettled immediately. Production synchronous reads should use\\n[TranslatorService.FlushEntryForKey] to land just the key they need.","params":[{"name":"self","desc":"","lua_type":"TranslatorService"}],"returns":[],"function_type":"static","source":{"line":396,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}},{"name":"FlushEntryForKey","desc":"Lands only what a synchronous read of a single key actually needs, leaving the rest of\\nthe batch queued for the normal end-of-frame flush. This lets a synchronous read\\n([JSONTranslator.FormatByKey]) guarantee the one key it reads is present without forcing\\n-- and paying for -- the whole pending batch early.\\n\\nOnly the locales a read can actually consult are landed (the example and every other\\nlocale in the entry stay queued), so a read costs a handful of targeted writes rather\\nthan one per locale in the entry.","params":[{"name":"self","desc":"","lua_type":"TranslatorService"},{"name":"translationKey","desc":"","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":414,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}},{"name":"GetLocalizationWriteCount","desc":"Returns the total number of raw mutating calls made to the localization table. Each\\nsuch call invalidates every AutoLocalize entry in the engine, so this is the cost we\\nwant to keep low. Primarily useful for diagnostics and regression tests.","params":[{"name":"self","desc":"","lua_type":"TranslatorService"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":477,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}},{"name":"ObserveTranslator","desc":"Observes Roblox translator","params":[{"name":"self","desc":"","lua_type":"TranslatorService"}],"returns":[{"desc":"","lua_type":"Observable<Translator>"}],"function_type":"static","source":{"line":606,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}},{"name":"PromiseTranslator","desc":"Promises the Roblox translator","params":[{"name":"self","desc":"","lua_type":"TranslatorService"}],"returns":[{"desc":"","lua_type":"Observable<Translator>"}],"function_type":"static","source":{"line":615,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}},{"name":"GetTranslator","desc":"Gets the current translator to use","params":[{"name":"self","desc":"","lua_type":"TranslatorService"}],"returns":[{"desc":"","lua_type":"Translator?"}],"function_type":"static","source":{"line":655,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}},{"name":"ObserveLocaleId","desc":"Observes the current locale id for this translator.","params":[{"name":"self","desc":"","lua_type":"TranslatorService"}],"returns":[{"desc":"","lua_type":"Observable<string>"}],"function_type":"static","source":{"line":664,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}},{"name":"GetLocaleId","desc":"Gets the localeId to use","params":[{"name":"self","desc":"","lua_type":"TranslatorService"}],"returns":[{"desc":"","lua_type":"string"}],"function_type":"static","source":{"line":711,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}}],"properties":[],"types":[],"name":"TranslatorService","desc":"Handles selecting the right locale/translator for Studio, and Roblox games.","source":{"line":7,"path":"src/clienttranslator/src/Shared/TranslatorService.lua"}}')}}]);